import { DeviceFrame } from '@refy-design/web';
import type { ComponentProps } from 'react';
const page =
  'iframe.html?id=components-molecules-sectionheader--playground&viewMode=story';
export function Example() {
  const args: Pick<
    ComponentProps<typeof DeviceFrame>,
    'variant' | 'src' | 'frameTitle' | 'address' | 'caption'
  > = {
    variant: 'browser',
    src: page,
    frameTitle: 'Browser example',
    address: 'refy.design',
    caption: 'Browser, 1280 px',
  };
  return (
    <div style={{ maxWidth: 640 }}>
      <DeviceFrame {...args} />
    </div>
  );
}

